async fn call(client: &Client, req: Request) -> Result<Reply, CallError> {
    let (tx, rx) = oneshot::channel::<Reply>();
    client.send(Envelope { id: next_id(), request: req, reply: tx }).await?;
    match tokio::time::timeout(Duration::from_secs(5), rx).await {
        Ok(Ok(reply)) => Ok(reply),
        Ok(Err(_)) => Err(CallError::ReplierGone),  // tx dropped
        Err(_) => Err(CallError::Timeout),          // deadline elapsed
    }
}

