fn call(pool: &Pool, req: Request) -> Result<Reply, CallError> {
    let (tx, rx) = std::sync::mpsc::channel::<Reply>();
    pool.submit(Envelope { id: next_id(), request: req, reply: tx })?;
    match rx.recv_timeout(Duration::from_secs(5)) {
        Ok(reply) => Ok(reply),
        Err(RecvTimeoutError::Timeout) => Err(CallError::Timeout),
        Err(RecvTimeoutError::Disconnected) => Err(CallError::ReplierGone),
    }
}
